class Solution:
    def isLongPressedName(self, name: str, typed: str) -> bool:
        def runs(s):
            res = []
            for c in s:
                if res and res[-1][0] == c:
                    res[-1][1] += 1
                else:
                    res.append([c, 1])
            return res
        rn, rt = runs(name), runs(typed)
        if len(rn) != len(rt):
            return False
        return all(a[0] == b[0] and b[1] >= a[1] for a, b in zip(rn, rt))

