class Solution {
public:
    vector<pair<char,int>> runs(const string& s) {
        vector<pair<char,int>> r;
        for (char c : s) {
            if (!r.empty() && r.back().first == c) r.back().second++;
            else r.push_back({c, 1});
        }
        return r;
    }
    bool isLongPressedName(string name, string typed) {
        auto rn = runs(name), rt = runs(typed);
        if (rn.size() != rt.size()) return false;
        for (int i = 0; i < rn.size(); i++)
            if (rn[i].first != rt[i].first || rt[i].second < rn[i].second)
                return false;
        return true;
    }
};

