class Solution {
    private List<int[]> runs(String s) {
        List<int[]> r = new ArrayList<>();
        for (char c : s.toCharArray()) {
            if (!r.isEmpty() && r.get(r.size()-1)[0] == c) r.get(r.size()-1)[1]++;
            else r.add(new int[]{c, 1});
        }
        return r;
    }
    public boolean isLongPressedName(String name, String typed) {
        List<int[]> rn = runs(name), rt = runs(typed);
        if (rn.size() != rt.size()) return false;
        for (int i = 0; i < rn.size(); i++)
            if (rn.get(i)[0] != rt.get(i)[0] || rt.get(i)[1] < rn.get(i)[1])
                return false;
        return true;
    }
}

