var isLongPressedName = function(name, typed) {
    const runs = s => {
        const r = [];
        for (const c of s) {
            if (r.length && r[r.length-1][0] === c) r[r.length-1][1]++;
            else r.push([c, 1]);
        }
        return r;
    };
    const rn = runs(name), rt = runs(typed);
    if (rn.length !== rt.length) return false;
    return rn.every(([c, n], i) => c === rt[i][0] && rt[i][1] >= n);
};

